import{_ as s,l as p,o as t,c as n,v as i,p as m,x as r,d as o,i as N,S as u,b as e}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"Post-LN 预热","description":"","frontmatter":{"title":"Post-LN 预热","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/post-ln-warmup.md","filePath":"llm/post-ln-warmup.md","lastUpdated":1789023840000}'),L={name:"llm/post-ln-warmup.md"};function d(P,a,h,c,E,B){const l=p("Mermaid");return t(),n("div",null,[a[1]||(a[1]=i('<h1 id="post-ln-预热" tabindex="-1">Post-LN 预热 <a class="header-anchor" href="#post-ln-预热" aria-label="Permalink to &quot;Post-LN 预热&quot;">​</a></h1><div class="epigraph"><p>LayerNorm 放在残差加法之后，初始化附近的雅可比会压低深层到嵌入的通路；没有足够长的学习率预热，深 Post-LN 常常根本走不进幂律段。</p><footer>—— Xiong et al., On Layer Normalization in the Transformer Architecture, 2020</footer></div><p><a href="/llm/activation-scale-drift">上一课</a>说明 Pre-LN 的病是总线 RMS 涨。缺口是另一侧：主干 <a href="/llm/pre-ln-post-ln">Pre-LN 与 Post-LN</a> 已经给出两种写法和梯度公路，本课不重推公式。当代默认 Pre-LN 之后，仍会遇到要复现原版 Transformer、或在浅网上追求 Post-LN 表示的情况。Xiong 等人指出：Post-LN 对 <strong>warmup</strong> 的依赖远强于 Pre-LN。稳定性单元把这件事从「LN 位置」里拆出来，专讲预热为何是 Post-LN 的生存条件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Post-LN：\\(x_{l+1}=\\mathrm{LN}(x_l+F(x_l))\\)。恒等路径经过 LN。初始化时 \\(F\\) 不小，LN 在残差与输入之间重新分配尺度，靠近嵌入的层分到的梯度过小。学习率一开始就处在峰值，底层几乎不更新、顶层先动，随后底层在错误的顶层特征下补课，容易炸或长期平台。Warmup 把 \\(\\eta\\) 从近 0 拉到峰值，给底层梯度一个「先小步对齐」的窗口。Xiong 等人的实验：同样深度，Post-LN 去掉 warmup 更易失败，Pre-LN 对 warmup 短得多仍可训。</p><p>这与 <a href="/llm/depth-scaled-init">深度缩放初始化</a> 互补：Fixup / DeepNorm 改的是 \\(F\\) 的起步幅度，warmup 改的是时间轴上的 \\(\\eta\\)。Post-LN 两者都更饿。只加长 warmup 而不缩小 \\(F\\)，深层仍可能在 warmup 结束后立刻不稳；只做 Fixup 而 \\(\\eta\\) 第一步就全开，同样危险。</p><p><span class="marginnote">warmup 步数应按 token 还是按 step 声明，与主干 <a href="/llm/lr-schedule">学习率日程</a> 一致。Post-LN 需要的是<strong>足够的数据量</strong>让底层统计稳定，不是「固定 2000 step」——大 batch 下同样 step 更少噪声，有时反而要更长 warmup（Goyal 的大 batch 规则）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若必须 Post-LN：</p><ol><li>warmup 显著长于同深度 Pre-LN 配方，并在触顶率、底层分层梯度上验收：warmup 结束前底层范数不应长期近 0。</li><li>峰值 \\(\\eta\\) 更保守。Xiong 的观察是 Pre-LN 允许更大 \\(\\eta\\)；把 Pre-LN 的 \\(\\eta\\) 贴到 Post-LN 上是常见炸因。</li><li>与深度缩放或 Admin 一类对 LN 的初始化修正一起用，不要指望单靠日程。</li></ol><p>若已经 Pre-LN：不要因为「论文都写 warmup」就复制一套为 Post-LN 设计的超长预热。过长 warmup 浪费峰值学习的 token，Chinchilla 预算下这是真金。Pre-LN 的 warmup 主要服务 Adam 的二阶矩估计与大 \\(\\eta\\)，不是 LN 雅可比。</p><p>日程形状（线性 warmup + 余弦 / WSD）仍按主干；本课只改<strong>长度与峰值</strong>对 LN 位置的依赖。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LN 的雅可比在输入偏离单位尺度时把残差通路缩小。Post-LN 每层做一次，深度方向连乘。Warmup 期间 \\(\\eta\\) 小，顶层不能把表示拉得太偏，底层才有机会在梯度尚未被压扁到零之前更新。Pre-LN 的主干不经过 LN，连乘不发生在公路上，warmup 不再承担「救公路」的任务。</p><p>这解释了为何浅 Post-LN（6–12 层翻译模型）可以很短甚至没有 warmup 仍成功，而深 Post-LN 不行：连乘因子随 \\(L\\) 指数变差。把 12 层翻译配方的 warmup 抄到 96 层解码器上，数量级不够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不主张回到 Post-LN 当大模型默认。只在你明确选择 Post-LN 时，把 warmup 写成稳定性约束。Hybrid / Sandwich LN 等变体对 warmup 的需求介于两者之间，应单独测底层梯度，不要线性插值步数当定理。</p><p>复现 2017 年原版翻译配方时，把当代 Pre-LN 大模型的短 warmup 贴回去，是最常见的「论文说可以训」却训崩的原因。下一课进入优化器内部：Adam 的 \\(\\varepsilon\\) 如何在已经「看起来稳」的网络上改写更新尺度。</p>',18)),(t(),m(u,null,{default:r(()=>[N(l,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20POST%5B%22Post-LN%EF%BC%9A%E5%85%AC%E8%B7%AF%E8%BF%87%20LN%22%5D%20--%3E%20JAC%5B%22%E9%9B%85%E5%8F%AF%E6%AF%94%E5%8E%8B%E5%BA%95%E5%B1%82%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20JAC%20--%3E%20WU%5B%22%E9%9C%80%E8%A6%81%E9%95%BF%20warmup%20%2B%20%E6%9B%B4%E5%B0%8F%E5%B3%B0%E5%80%BC%20eta%22%5D%0A%20%20PRE%5B%22Pre-LN%EF%BC%9A%E5%85%AC%E8%B7%AF%E4%B8%8D%E8%BF%87%20LN%22%5D%20--%3E%20SHORT%5B%22warmup%20%E4%B8%BB%E8%A6%81%E4%B8%BA%20Adam%20%E7%BB%9F%E8%AE%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[o("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Post-LN 的恒等路径经过 LN，深层初始化附近底层梯度被压；warmup 是生存条件。"),e("li",null,"同深度下 Post-LN 的峰值 \\(\\eta\\) 应小于 Pre-LN；长度按 token 声明，随 \\(L\\) 加。"),e("li",null,"深度缩放与 warmup 互补，不能互相替代。"),e("li",null,"Pre-LN 大模型不要照抄为 Post-LN 设计的超长预热。"),e("li",null,"出处：Xiong et al., 2020；日程背景见 Goyal 等大 batch warmup。")],-1))])}const f=s(L,[["render",d]]);export{w as __pageData,f as default};
